import subprocess

def test_ps_command():
    try:
        # Example of running a ps command with flags
        result = subprocess.run(["ps", "aux"], capture_output=True, text=True, check=True)
        print(result.stdout)
    except subprocess.CalledProcessError as e:
        print(f"Error executing ps command: {e}")

test_ps_command()
